import "./yacht" for Yacht
import "wren-testie/testie" for Testie, Expect

Testie.test("Yacht") { |do, skip|
  do.test("Yacht") {
    var dice = [5, 5, 5, 5, 5]
    var category = "yacht"
    var expected = 50
    Expect.value(Yacht.score(dice, category)).toEqual(expected)
  }

  skip.test("Not Yacht") {
    var dice = [1, 3, 3, 2, 5]
    var category = "yacht"
    var expected = 0
    Expect.value(Yacht.score(dice, category)).toEqual(expected)
  }

  skip.test("Ones") {
